@implementation MapApiCodecReader
- (nullable id)readValueOfType:(UInt8)type {
  switch (type) {
    case 128: 
      return [AddLayerPointObjectsMessage fromList:[self readValue]];
    case 129: 
      return [AddMarkersWithPhotoMessage fromList:[self readValue]];
    case 130: 
      return [AddressAdmDivMessage fromList:[self readValue]];
    case 131: 
      return [AddressComponentMessage fromList:[self readValue]];
    case 132: 
      return [AddressLocationMessage fromList:[self readValue]];
    case 133: 
      return [AddressMessage fromList:[self readValue]];
    case 134: 
      return [AddressNumberMessage fromList:[self readValue]];
    case 135: 
      return [AddressStreetMessage fromList:[self readValue]];
    case 136: 
      return [ApartmentRangeMessage fromList:[self readValue]];
    case 137: 
      return [AttributeMessage fromList:[self readValue]];
    case 138: 
      return [BuildingLevelsMessage fromList:[self readValue]];
